content.content:
        """Every state the trace visits, from the source of the first step."""
        if not self.transitions:
            return []
        return ([self.transitions[0].src]
                + [step.dst for step in self.transitions])

    def get_variable_trace(self, var_name):
        """Return the values `var_name` takes across all states of the trace."""
        return [state.get(var_name) for state in self.states]

    def __len__(self):
        return len(self.transitions)

    def __repr__(self):
        return "Counterexample(length=%d, %r)" % (self.length, self.states)


# --------------------------------------------------------------------------
# Small z3 helpers
# --------------------------------------------------------------------------


def _conjuncts(expr):
    """Split a (possibly nested) conjunction into its top level conjuncts."""
    if z3.is_and(expr):
        return [part for child in expr.children() for part in _conjuncts(child)]
    return [expr]


#: Declaration kinds that combine boolean subterms rather than being atoms.
_CONNECTIVE_KINDS = frozenset(
    kind for kind in (getattr(z3, name, None) for name in
                      ("Z3_OP_AND", "Z3_OP_OR", "Z3_OP_NOT", "Z3_OP_IMPLIES",
                       "Z3_OP_XOR", "Z3_OP_ITE", "Z3_OP_IFF"))
    if kind is not None)


def _is_connective(expr):
    """True when `expr` is a boolean operator whose children hold the atoms."""
    if not z3.is_app(expr):
        return False
    kind = expr.decl().kind()
    if kind == z3.Z3_OP_EQ:
        # An equality between booleans is an iff, not an atom.
        return all(z3.is_bool(child) for child in expr.children())
    return kind in _CONNECTIVE_KINDS


def _atoms(expr, found=None):
    """Collect the atomic boolean subterms of `expr` (comparisons, literals)."""
    found = [] if found is None else found
    if not z3.is_bool(expr):
        return found
    if _is_connective(expr):
        for child in expr.children():
            _atoms(child, found)
    elif not (z3.is_true(expr) or z3.is_false(expr)):
        if not any(expr.eq(seen) for seen in found):
            found.append(expr)
    return found


def _size(expr, budget=None):
    """Count the nodes of `expr`, stopping early once `budget` is exceeded."""
    seen = set()
    stack = [expr]
    total = 0
    while stack:
        node = stack.pop()
        key = node.get_id()
        if key in seen:
            continue
        seen.add(key)
        total += 1
        if budget is not None and total > budget:
            return total
        if z3.is_app(node):
            stack.extend(node.children())
    return total


def _is_trivial(expr):
    """True when `expr` simplifies to a constant and so carries no information."""
    try:
        simplified = z3.simplify(expr)
    except z3.Z3Exception:
        return True
    return z3.is_true(simplified) or z3.is_false(simplified)


def _valid(formula):
    """True when `formula` holds for every assignment."""
    solver = z3.Solver()
    solver.add(z3.Not(formula))
    return solver.check() == z3.unsat


def _satisfiable(*formulas):
    """True when the conjunction of `formulas` has a model."""
    solver = z3.Solver()
    solver.add(*formulas)
    return solver.check() == z3.sat


class _NameCollector(dict):
    """A variable environment that mints a fresh ``Int`` for every lookup.

    Passing one of these to a system's ``init``/``trans``/``safety`` callables
    records exactly which program variables they mention, so a caller does not
    have to spell the variable list out twice.
    """

    def __missing__(self, key):
        value = z3.Int(key)
        self[key] = value
        return value


def collect_var_names(init_cond, trans_rel, safety):
    """Return the sorted variable names mentioned by a transition system."""
    names = set()
    for build in (lambda: init_cond(_probe(names)),
                  lambda: trans_rel(_probe(names), _probe(names)),
                  lambda: safety(_probe(names))):
        try:
            build()
        except Exception:
            continue
    return sorted(names)


def _probe(sink):
    """Return a collector that records every name it is asked for in `sink`."""

    class _Sink(_NameCollector):
        def __missing__(self, key):
            sink.add(key)
            return _NameCollector.__missing__(self, key)

    return _Sink()


def _env(names, suffix=""):
    """Return ``{name: Int(name + suffix)}`` for every name in `names`."""
    return {name: z3.Int(name + suffix) for name in names}


def _bind(env, state):
    """Return the equalities pinning the variables of `env` to `state`."""
    return [env[name] == z3.IntVal(int(value))
            for name, value in state.values.items() if name in env]


def _read_state(model, env):
    """Read the values `model` assigns to the variables of `env`."""
    values = {}
    for name, const in env.items():
        value = model.eval(const, model_completion=True)
        values[name] = value.as_long() if hasattr(value, "as_long") else 0
    return State(values)


